import{_ as l,W as o,s as c,u as r,I as a,ah as i,w as s,Z as e,A as t}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const f=JSON.parse('{"title":"awk 系列：怎样使用 awk 变量、数值表达式以及赋值运算符 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：怎样使用 awk 变量、数值表达式以及赋值运算符 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：怎样使用 awk 变量、数值表达式以及赋值运算符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：怎样使用 awk 变量、数值表达式以及赋值运算符 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 8 - Learn How to Use Awk Variables, Numeric Expressions and Assignment Operators","title":"awk 系列：怎样使用 awk 变量、数值表达式以及赋值运算符","tag":"awk"},"relativePath":"awk/Part 8 - Learn How to Use Awk Variables, Numeric Expressions and Assignment Operators.md","filePath":"[post].md"}'),d={name:"awk/Part 8 - Learn How to Use Awk Variables, Numeric Expressions and Assignment Operators.md"};function m(u,n,g,h,w,k){const p=o("Link");return r(),c("div",null,[n[27]||(n[27]=a("h1",{id:"awk-系列-怎样使用-awk-变量、数值表达式以及赋值运算符",tabindex:"-1"},[s("awk 系列：怎样使用 awk 变量、数值表达式以及赋值运算符 "),a("a",{class:"header-anchor",href:"#awk-系列-怎样使用-awk-变量、数值表达式以及赋值运算符","aria-label":"Permalink to awk 系列：怎样使用 awk 变量、数值表达式以及赋值运算符"},"​")],-1)),a("p",null,[n[1]||(n[1]=s("我觉得 ")),e(p,{href:"https://linux.cn/article-7586-1.html"},{default:t(()=>n[0]||(n[0]=[s("awk 系列")])),_:1}),n[2]||(n[2]=s(" 将会越来越好，在本系列的前七节我们讨论了在 Linux 中处理文件和筛选字符串所需要的一些 awk 命令基础。"))]),n[28]||(n[28]=i(`<p>在这一部分，我们将会进入 awk 更高级的部分，使用 awk 处理更复杂的文本和进行字符串过滤操作。因此，我们将会讲到 Awk 的一些特性，诸如变量、数值表达式和赋值运算符。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Learn-Awk-Variables-Numeric-Expressions-Assignment-Operators.png" alt=""></p><p><em>学习 Awk 变量，数值表达式和赋值运算符</em></p><p>你可能已经在很多编程语言中接触过它们，比如 shell，C，Python 等；这些概念在理解上和这些语言没有什么不同，所以在这一小节中你不用担心很难理解，我们将会简短的提及常用的一些 awk 特性。</p><p>这一小节可能是 awk 命令里最容易理解的部分，所以放松点，我们开始吧。</p><h3 id="_1-awk-变量" tabindex="-1">1. Awk 变量 <a class="header-anchor" href="#_1-awk-变量" aria-label="Permalink to 1. Awk 变量">​</a></h3><p>在很多编程语言中，变量就是一个存储了值的占位符，当你在程序中新建一个变量的时候，程序一运行就会在内存中创建一些空间，你为变量赋的值会存储在这些内存空间上。</p><p>你可以像下面这样定义 shell 变量一样定义 Awk 变量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>variable_name=value</span></span></code></pre></div><p>上面的语法：</p><ul><li><code>variable_name</code>: 为定义的变量的名字</li><li><code>value</code>: 为变量赋的值</li></ul><p>再看下面的一些例子:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>computer_name=”tecmint.com”</span></span>
<span class="line"><span>port_no=”22”</span></span>
<span class="line"><span>email=”admin@tecmint.com”</span></span>
<span class="line"><span>server=computer_name</span></span></code></pre></div><p>观察上面的简单的例子，在定义第一个变量的时候，值 &#39;tecmint.com&#39; 被赋给了 &#39;computer_name&#39; 变量。</p><p>此外，值 22 也被赋给了 port_no 变量，把一个变量的值赋给另一个变量也是可以的，在最后的例子中我们把变量 computer_name 的值赋给了变量 server。</p>`,15)),a("p",null,[n[4]||(n[4]=s("你可以看看")),e(p,{href:"https://linux.cn/article-7587-1.html"},{default:t(()=>n[3]||(n[3]=[s("本系列的第 2 节")])),_:1}),n[5]||(n[5]=s("中提到的字段编辑，我们讨论了 awk 怎样将输入的行分隔为若干字段并且使用标准字段访问操作符 ")),n[6]||(n[6]=a("code",null,"$",-1)),n[7]||(n[7]=s(" 来访问拆分出来的不同字段。我们也可以像下面这样使用变量为字段赋值。"))]),n[29]||(n[29]=i(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>first_name=$2</span></span>
<span class="line"><span>second_name=$3</span></span></code></pre></div><p>在上面的例子中，变量 first_name 的值设置为第二个字段，second_name 的值设置为第三个字段。</p>`,2)),a("p",null,[n[9]||(n[9]=s("再举个例子，有一个名为 names.txt 的文件，这个文件包含了一个应用程序的用户列表，这个用户列表包含了用户的名和姓以及性别。可以使用 ")),e(p,{href:"http://www.tecmint.com/13-basic-cat-command-examples-in-linux/"},{default:t(()=>n[8]||(n[8]=[s("cat 命令")])),_:1}),n[10]||(n[10]=s(" 查看文件内容："))]),n[30]||(n[30]=i(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat names.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/List-File-Content-Using-cat-Command.png" alt=""></p><p><em>使用 cat 命令查看列表文件内容</em></p><p>然后，我们也可以使用下面的 awk 命令把列表中第一个用户的第一个和第二个名字分别存储到变量 first_name 和 second_name 上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;/Aaron/{ first_name=$2 ; second_name=$3 ; print first_name, second_name ; }&#39; names.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Store-Variables-Using-Awk-Command.png" alt=""></p><p><em>使用 Awk 命令为变量赋值</em></p><p>再看一个例子，当你在终端运行 &#39;uname -a&#39; 时，它可以打印出所有的系统信息。</p><p>第二个字段包含了你的主机名，因此，我们可以像下面这样把它赋给一个叫做 hostname 的变量并且用 awk 打印出来。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ uname -a</span></span>
<span class="line"><span>$ uname -a | awk &#39;{hostname=$2 ; print hostname ; }&#39;</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Store-Command-Output-to-Variable-Using-Awk.png" alt=""></p><p><em>使用 Awk 把命令的输出赋给变量</em></p><h3 id="_2-数值表达式" tabindex="-1">2. 数值表达式 <a class="header-anchor" href="#_2-数值表达式" aria-label="Permalink to 2. 数值表达式">​</a></h3><p>在 Awk 中，数值表达式使用下面的数值运算符组成：</p><ul><li><code>*</code> : 乘法运算符</li><li><code>+</code> : 加法运算符</li><li><code>/</code> : 除法运算符</li><li><code>-</code> : 减法运算符</li><li><code>%</code> : 取模运算符</li><li><code>^</code> : 指数运算符</li></ul><p>数值表达式的语法是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ operand1 operator operand2</span></span></code></pre></div><p>上面的 operand1 和 operand2 可以是数值和变量，运算符可以是上面列出的任意一种。</p><p>下面是一些展示怎样使用数值表达式的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>counter=0</span></span>
<span class="line"><span>num1=5</span></span>
<span class="line"><span>num2=10</span></span>
<span class="line"><span>num3=num2-num1</span></span>
<span class="line"><span>counter=counter+1</span></span></code></pre></div><p>要理解 Awk 中数值表达式的用法，我们可以看看下面的例子，文件 domians.txt 里包括了所有属于 Tecmint 的域名。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>windows.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>windows.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span></code></pre></div><p>可以使用下面的命令查看文件的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat domains.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/View-Contents-of-File.png" alt=""></p><p><em>查看文件内容</em></p><p>如果想要计算出域名 tecmint.com 在文件中出现的次数，我们就可以通过写一个简单的脚本实现这个功能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for file in $@; do</span></span>
<span class="line"><span>if [ -f $file ] ; then</span></span>
<span class="line"><span>#print out filename</span></span>
<span class="line"><span>echo &quot;File is: $file&quot;</span></span>
<span class="line"><span>#print a number incrementally for every line containing tecmint.com </span></span>
<span class="line"><span>awk  &#39;/^tecmint.com/ { counter=counter+1 ; printf &quot;%s\\n&quot;, counter ; }&#39;   $file</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>#print error info incase input is not a file</span></span>
<span class="line"><span>echo &quot;$file is not a file, please specify a file.&quot; &gt;&amp;2 &amp;&amp; exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>#terminate script with exit code 0 in case of successful execution </span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Shell-Script-to-Count-a-String-in-File.png" alt=""></p><p><em>计算一个字符串或文本在文件中出现次数的 shell 脚本</em></p><p>写完脚本后保存并赋予执行权限，当我们使用文件运行脚本的时候，文件 domains.txt 作为脚本的输入，我们会得到下面的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ./script.sh  ~/domains.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Script-To-Count-String.png" alt=""></p><p><em>计算字符串或文本出现次数的脚本</em></p><p>从脚本执行后的输出中，可以看到在文件 domains.txt 中包含域名 tecmint.com 的地方有 6 行，你可以自己计算进行验证。</p><h3 id="_3-赋值操作符" tabindex="-1">3. 赋值操作符 <a class="header-anchor" href="#_3-赋值操作符" aria-label="Permalink to 3. 赋值操作符">​</a></h3><p>我们要说的最后的 Awk 特性是赋值操作符，下面列出的只是 awk 中的部分赋值运算符：</p><ul><li><code>*=</code> : 乘法赋值操作符</li><li><code>+=</code> : 加法赋值操作符</li><li><code>/=</code> : 除法赋值操作符</li><li><code>-=</code> : 减法赋值操作符</li><li><code>%=</code> : 取模赋值操作符</li><li><code>^=</code> : 指数赋值操作符</li></ul><p>下面是 Awk 中最简单的一个赋值操作的语法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ variable_name=variable_name operator operand</span></span></code></pre></div><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>counter=0</span></span>
<span class="line"><span>counter=counter+1</span></span>
<span class="line"><span>num=20</span></span>
<span class="line"><span>num=num-1</span></span></code></pre></div><p>你可以使用在 awk 中使用上面的赋值操作符使命令更简短，从先前的例子中，我们可以使用下面这种格式进行赋值操作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>variable_name operator=operand</span></span>
<span class="line"><span>counter=0</span></span>
<span class="line"><span>counter+=1</span></span>
<span class="line"><span>num=20</span></span>
<span class="line"><span>num-=1</span></span></code></pre></div><p>因此，我们可以在 shell 脚本中改变 awk 命令，使用上面提到的 += 操作符:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for file in $@; do</span></span>
<span class="line"><span>if [ -f $file ] ; then</span></span>
<span class="line"><span>#print out filename</span></span>
<span class="line"><span>echo &quot;File is: $file&quot;</span></span>
<span class="line"><span>#print a number incrementally for every line containing tecmint.com </span></span>
<span class="line"><span>awk  &#39;/^tecmint.com/ { counter+=1 ; printf  &quot;%s\\n&quot;,  counter ; }&#39;   $file</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>#print error info incase input is not a file</span></span>
<span class="line"><span>echo &quot;$file is not a file, please specify a file.&quot; &gt;&amp;2 &amp;&amp; exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>#terminate script with exit code 0 in case of successful execution </span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Alter-Shell-Script.png" alt=""></p><p><em>修改了的 shell 脚本</em></p>`,48)),a("p",null,[n[12]||(n[12]=s("在 ")),e(p,{href:"https://linux.cn/article-7586-1.html"},{default:t(()=>n[11]||(n[11]=[s("awk 系列")])),_:1}),n[13]||(n[13]=s(" 的这一部分，我们讨论了一些有用的 awk 特性，有变量，使用数值表达式和赋值运算符，还有一些使用它们的实例。"))]),n[31]||(n[31]=a("p",null,"这些概念和其他的编程语言没有任何不同，但是可能在 awk 中有一些意义上的区别。",-1)),n[32]||(n[32]=a("p",null,"在本系列的第 9 节，我们会学习更多的 awk 特性，比如特殊格式： BEGIN 和 END。请继续关注。",-1)),n[33]||(n[33]=a("hr",null,null,-1)),a("p",null,[n[15]||(n[15]=s("via: ")),e(p,{href:"http://www.tecmint.com/learn-awk-variables-numeric-expressions-and-assignment-operators/"},{default:t(()=>n[14]||(n[14]=[s("http://www.tecmint.com/learn-awk-variables-numeric-expressions-and-assignment-operators/")])),_:1})]),a("p",null,[n[19]||(n[19]=s("作者：")),e(p,{href:"http://www.tecmint.com/author/aaronkili/"},{default:t(()=>n[16]||(n[16]=[s("Aaron Kili")])),_:1}),n[20]||(n[20]=s(" 译者：")),e(p,{href:"https://github.com/vim-kakali"},{default:t(()=>n[17]||(n[17]=[s("vim-kakali")])),_:1}),n[21]||(n[21]=s(" 校对：")),e(p,{href:"https://github.com/wxy"},{default:t(()=>n[18]||(n[18]=[s("wxy")])),_:1})]),a("p",null,[n[24]||(n[24]=s("本文由 ")),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>n[22]||(n[22]=[s("LCTT")])),_:1}),n[25]||(n[25]=s(" 原创编译，")),e(p,{href:"https://linux.cn/"},{default:t(()=>n[23]||(n[23]=[s("Linux中国")])),_:1}),n[26]||(n[26]=s(" 荣誉推出"))])])}const x=l(d,[["render",m]]);export{f as __pageData,x as default};
